//! What the project brings itself, so the engine does not overwrite it: the real `next` package (the
//! same folder also runs with `next dev`, e.g. the `build/nextjs` app generated by comx) and its own
//! `core` module (`core/index.ts`, mapped by the project's tsconfig).

use std::path::{Path, PathBuf};

/// `next` is installed from npm (not the stub package earlier engine versions wrote)
pub fn has_real_next(root: &Path) -> bool {
    crate::store::packages_dir(root).join("next/dist").is_dir()
}

/// The project's own `core` module, which `import ... from "core"` resolves to instead of `.nata/core.ts`
pub fn project_core(root: &Path) -> Option<PathBuf> {
    ["core/index.ts", "core/index.tsx", "core/index.js"].iter().map(|p| root.join(p)).find(|p| p.is_file())
}

/// A Next.js app generated by comx (`<workspace>/build/nextjs`): backend modules behind an RPC server
pub fn is_comx_build(root: &Path) -> bool {
    root.join("core/rpc/proxy-dispatcher.ts").is_file() && root.join("config/plugins.json").is_file()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_real_next_core_and_comx_build() {
        let dir = std::env::temp_dir().join(format!("nata_project_{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let root = dir.as_path();
        assert!(!has_real_next(root));
        assert!(project_core(root).is_none());
        assert!(!is_comx_build(root));

        std::fs::create_dir_all(root.join("node_modules/next/dist")).unwrap();
        std::fs::create_dir_all(root.join("core/rpc")).unwrap();
        std::fs::create_dir_all(root.join("config")).unwrap();
        std::fs::write(root.join("core/index.ts"), "export {};").unwrap();
        std::fs::write(root.join("core/rpc/proxy-dispatcher.ts"), "export {};").unwrap();
        std::fs::write(root.join("config/plugins.json"), "[]").unwrap();

        assert!(has_real_next(root));
        assert_eq!(project_core(root), Some(root.join("core/index.ts")));
        assert!(is_comx_build(root));
        let _ = std::fs::remove_dir_all(&dir);
    }
}
